insert into public.exercises
  (id, owner_id, name, primary_muscle, secondary_muscles, equipment, category, difficulty, tracking_type, instructions, is_ranked)
values
  ('bench-press', null, 'Bench Press', 'chest', array['triceps', 'shoulders']::text[], 'Barbell', 'Push', 'Intermediate', 'weighted', 'Lie on a flat bench with feet planted. Lower the bar to mid-chest under control, then press it back up until your arms are straight.', true),
  ('incline-bench', null, 'Incline Bench Press', 'chest', array['shoulders', 'triceps']::text[], 'Barbell', 'Push', 'Intermediate', 'weighted', 'Set the bench to a 30 to 45 degree angle. Lower the bar to your upper chest and press up without letting your shoulders roll forward.', true),
  ('db-bench', null, 'Dumbbell Bench Press', 'chest', array['triceps', 'shoulders']::text[], 'Dumbbell', 'Push', 'Beginner', 'weighted', 'Lie on a flat bench holding dumbbells at chest level. Press them up and slightly together, then lower until you feel a stretch in your chest.', false),
  ('incline-db-press', null, 'Incline Dumbbell Press', 'chest', array['shoulders', 'triceps']::text[], 'Dumbbell', 'Push', 'Beginner', 'weighted', 'On an incline bench, press the dumbbells from shoulder height to full extension, then lower them slowly to the sides of your upper chest.', false),
  ('chest-fly', null, 'Chest Fly', 'chest', array['shoulders']::text[], 'Dumbbell', 'Push', 'Beginner', 'weighted', 'Lie on a bench with dumbbells above your chest and a slight bend in your elbows. Open your arms wide in an arc, then squeeze them back together.', false),
  ('cable-fly', null, 'Cable Fly', 'chest', array['shoulders']::text[], 'Cable', 'Push', 'Beginner', 'weighted', 'Stand between two cable stacks with the handles at shoulder height. Step forward and bring your hands together in front of your chest in a wide hugging motion.', false),
  ('pec-deck', null, 'Pec Deck', 'chest', array['shoulders']::text[], 'Machine', 'Push', 'Beginner', 'weighted', 'Sit with your back flat against the pad and your forearms on the arm pads. Bring the pads together in front of you, pause, and return slowly.', false),
  ('push-up', null, 'Push-up', 'chest', array['triceps', 'shoulders', 'abs']::text[], 'Bodyweight', 'Push', 'Beginner', 'bodyweight', 'Start in a plank with hands under your shoulders. Lower your chest to just above the floor with a straight body, then push back up.', false),
  ('deadlift', null, 'Deadlift', 'back', array['hamstrings', 'glutes']::text[], 'Barbell', 'Pull', 'Advanced', 'weighted', 'Stand with the bar over mid-foot. Hinge at the hips, grip the bar, brace your core and stand up by driving through your legs while keeping the bar close to you.', true),
  ('barbell-row', null, 'Barbell Row', 'back', array['biceps', 'shoulders']::text[], 'Barbell', 'Pull', 'Intermediate', 'weighted', 'Hinge forward with a flat back holding the bar. Pull it to your lower ribs, squeeze your shoulder blades together, then lower under control.', true),
  ('db-row', null, 'Dumbbell Row', 'back', array['biceps']::text[], 'Dumbbell', 'Pull', 'Beginner', 'weighted', 'Support one hand and knee on a bench. Pull the dumbbell to your hip keeping your elbow close to your body, then lower it fully.', false),
  ('pull-up', null, 'Pull-up', 'back', array['biceps']::text[], 'Bodyweight', 'Pull', 'Intermediate', 'bodyweight', 'Hang from a bar with an overhand grip. Pull your chest toward the bar by driving your elbows down, then lower to a full hang.', false),
  ('assisted-pull-up', null, 'Assisted Pull-up', 'back', array['biceps']::text[], 'Machine', 'Pull', 'Beginner', 'assisted', 'Kneel on the assist pad and grip the bars. Pull yourself up until your chin passes the bar. Log the assistance weight; less assistance means more strength.', false),
  ('lat-pulldown', null, 'Lat Pulldown', 'back', array['biceps']::text[], 'Cable', 'Pull', 'Beginner', 'weighted', 'Sit with thighs secured under the pad. Pull the bar to your upper chest by driving your elbows down and back, then let it rise slowly.', true),
  ('seated-row', null, 'Seated Cable Row', 'back', array['biceps']::text[], 'Cable', 'Pull', 'Beginner', 'weighted', 'Sit tall with a slight knee bend. Pull the handle to your stomach, squeeze your shoulder blades together, and return with control.', false),
  ('t-bar-row', null, 'T-Bar Row', 'back', array['biceps', 'shoulders']::text[], 'Barbell', 'Pull', 'Intermediate', 'weighted', 'Straddle the bar and hinge forward with a flat back. Pull the handle toward your chest, pause, and lower slowly.', false),
  ('straight-arm-pulldown', null, 'Straight Arm Pulldown', 'back', array['triceps']::text[], 'Cable', 'Pull', 'Beginner', 'weighted', 'Stand facing a high cable with straight arms. Sweep the bar down to your thighs using your lats, then return slowly.', false),
  ('overhead-press', null, 'Shoulder Press', 'shoulders', array['triceps']::text[], 'Barbell', 'Push', 'Intermediate', 'weighted', 'Stand with the bar at shoulder height. Brace your core and press it overhead until your arms lock out, then lower it back to your shoulders.', true),
  ('db-shoulder-press', null, 'Dumbbell Shoulder Press', 'shoulders', array['triceps']::text[], 'Dumbbell', 'Push', 'Beginner', 'weighted', 'Sit or stand holding dumbbells at shoulder height. Press them overhead until your arms are straight, then lower with control.', false),
  ('lateral-raise', null, 'Lateral Raise', 'shoulders', array[]::text[], 'Dumbbell', 'Push', 'Beginner', 'weighted', 'Stand with dumbbells at your sides. Raise your arms out to shoulder height with a slight elbow bend, then lower slowly.', false),
  ('front-raise', null, 'Front Raise', 'shoulders', array['chest']::text[], 'Dumbbell', 'Push', 'Beginner', 'weighted', 'Hold dumbbells in front of your thighs. Raise them straight ahead to shoulder height without swinging, then lower slowly.', false),
  ('rear-delt-fly', null, 'Rear Delt Fly', 'shoulders', array['back']::text[], 'Dumbbell', 'Pull', 'Beginner', 'weighted', 'Hinge forward holding dumbbells below your chest. Raise your arms out to the sides, squeezing your rear shoulders, then lower slowly.', false),
  ('face-pull', null, 'Face Pull', 'shoulders', array['back']::text[], 'Cable', 'Pull', 'Beginner', 'weighted', 'Set a rope at face height. Pull it toward your face while flaring your elbows out, then extend your arms back slowly.', false),
  ('upright-row', null, 'Upright Row', 'shoulders', array['biceps']::text[], 'Barbell', 'Pull', 'Intermediate', 'weighted', 'Hold the bar in front of your thighs. Pull it up toward your chest leading with your elbows, then lower it slowly.', false),
  ('barbell-curl', null, 'Barbell Curl', 'biceps', array[]::text[], 'Barbell', 'Pull', 'Beginner', 'weighted', 'Stand holding the bar with an underhand grip. Curl it to shoulder height keeping your elbows still, then lower slowly.', true),
  ('db-curl', null, 'Dumbbell Curl', 'biceps', array[]::text[], 'Dumbbell', 'Pull', 'Beginner', 'weighted', 'Hold dumbbells at your sides with palms forward. Curl them up, squeeze at the top, and lower under control.', false),
  ('hammer-curl', null, 'Hammer Curl', 'biceps', array[]::text[], 'Dumbbell', 'Pull', 'Beginner', 'weighted', 'Hold dumbbells with palms facing each other. Curl them up without rotating your wrists, then lower slowly.', false),
  ('preacher-curl', null, 'Preacher Curl', 'biceps', array[]::text[], 'Barbell', 'Pull', 'Beginner', 'weighted', 'Rest your upper arms on the preacher pad. Curl the bar up and lower it until your arms are almost straight.', false),
  ('cable-curl', null, 'Cable Curl', 'biceps', array[]::text[], 'Cable', 'Pull', 'Beginner', 'weighted', 'Stand facing a low cable with a straight bar. Curl it up keeping your elbows at your sides, then lower slowly.', false),
  ('concentration-curl', null, 'Concentration Curl', 'biceps', array[]::text[], 'Dumbbell', 'Pull', 'Beginner', 'weighted', 'Sit with your elbow braced against your inner thigh. Curl the dumbbell up slowly, squeeze, and lower with control.', false),
  ('tricep-pushdown', null, 'Triceps Pushdown', 'triceps', array[]::text[], 'Cable', 'Push', 'Beginner', 'weighted', 'Stand at a high cable with elbows pinned to your sides. Push the bar down until your arms are straight, then let it rise slowly.', false),
  ('overhead-extension', null, 'Overhead Extension', 'triceps', array[]::text[], 'Dumbbell', 'Push', 'Beginner', 'weighted', 'Hold one dumbbell overhead with both hands. Lower it behind your head by bending your elbows, then extend back up.', false),
  ('skull-crusher', null, 'Skull Crushers', 'triceps', array[]::text[], 'Barbell', 'Push', 'Intermediate', 'weighted', 'Lie on a bench holding the bar above your chest. Bend your elbows to lower it toward your forehead, then extend back up.', false),
  ('close-grip-bench', null, 'Close-Grip Bench Press', 'triceps', array['chest', 'shoulders']::text[], 'Barbell', 'Push', 'Intermediate', 'weighted', 'Bench press with your hands about shoulder-width apart and elbows tucked. Lower to your lower chest and press up.', true),
  ('dips', null, 'Dips', 'triceps', array['chest', 'shoulders']::text[], 'Bodyweight', 'Push', 'Intermediate', 'bodyweight', 'Support yourself on parallel bars. Lower until your upper arms are about parallel to the floor, then press back up to straight arms.', false),
  ('squat', null, 'Squat', 'quads', array['glutes', 'hamstrings']::text[], 'Barbell', 'Legs', 'Intermediate', 'weighted', 'Set the bar on your upper back and brace your core. Sit down and back until your thighs are at least parallel, then drive up through your whole foot.', true),
  ('front-squat', null, 'Front Squat', 'quads', array['glutes', 'abs']::text[], 'Barbell', 'Legs', 'Advanced', 'weighted', 'Rest the bar on your front shoulders with elbows high. Squat down keeping your torso upright, then stand back up.', true),
  ('leg-press', null, 'Leg Press', 'quads', array['glutes', 'hamstrings']::text[], 'Machine', 'Legs', 'Beginner', 'weighted', 'Sit with your feet shoulder-width on the platform. Lower the sled until your knees reach about 90 degrees, then press without locking out hard.', true),
  ('leg-extension', null, 'Leg Extension', 'quads', array[]::text[], 'Machine', 'Legs', 'Beginner', 'weighted', 'Sit with the pad on your lower shins. Extend your legs until they are straight, squeeze your quads, and lower slowly.', false),
  ('lunge', null, 'Lunges', 'quads', array['glutes', 'hamstrings']::text[], 'Dumbbell', 'Legs', 'Beginner', 'weighted', 'Step forward into a lunge until both knees are bent about 90 degrees, then push back to the start. Alternate legs.', false),
  ('bulgarian-split-squat', null, 'Bulgarian Split Squat', 'quads', array['glutes']::text[], 'Dumbbell', 'Legs', 'Intermediate', 'weighted', 'Place your rear foot on a bench behind you. Lower straight down until your front thigh is parallel, then drive back up.', false),
  ('rdl', null, 'Romanian Deadlift', 'hamstrings', array['glutes', 'back']::text[], 'Barbell', 'Legs', 'Intermediate', 'weighted', 'Hold the bar at hip height. Push your hips back with a slight knee bend, lowering the bar along your legs until you feel a hamstring stretch, then stand up.', true),
  ('leg-curl', null, 'Leg Curl', 'hamstrings', array[]::text[], 'Machine', 'Legs', 'Beginner', 'weighted', 'Lie or sit with the pad against your lower calves. Curl your heels toward your glutes, squeeze, and return slowly.', false),
  ('hip-thrust', null, 'Hip Thrust', 'glutes', array['hamstrings']::text[], 'Barbell', 'Legs', 'Intermediate', 'weighted', 'Sit with your upper back against a bench and the bar over your hips. Drive your hips up until your body is straight from shoulders to knees, squeeze, and lower.', true),
  ('calf-raise', null, 'Calf Raises', 'calves', array[]::text[], 'Machine', 'Legs', 'Beginner', 'weighted', 'Stand with the balls of your feet on a platform. Rise as high as you can onto your toes, pause, then lower to a full stretch.', true),
  ('crunch', null, 'Crunches', 'abs', array[]::text[], 'Bodyweight', 'Core', 'Beginner', 'bodyweight', 'Lie on your back with knees bent. Curl your shoulders off the floor by contracting your abs, then lower slowly.', false),
  ('cable-crunch', null, 'Cable Crunches', 'abs', array[]::text[], 'Cable', 'Core', 'Beginner', 'weighted', 'Kneel below a high cable holding the rope by your head. Curl your torso down toward your knees using your abs, then return slowly.', true),
  ('hanging-leg-raise', null, 'Hanging Leg Raises', 'abs', array[]::text[], 'Bodyweight', 'Core', 'Intermediate', 'bodyweight', 'Hang from a bar. Raise your legs until they are at least parallel to the floor without swinging, then lower under control.', false),
  ('plank', null, 'Planks', 'abs', array['shoulders']::text[], 'Bodyweight', 'Core', 'Beginner', 'timed', 'Hold a straight line from head to heels on your forearms and toes, with your core braced and hips level. Log the time held.', false),
  ('ab-wheel', null, 'Ab Wheel', 'abs', array['shoulders']::text[], 'Other', 'Core', 'Advanced', 'bodyweight', 'Kneel holding the wheel. Roll forward as far as you can with a flat back, then pull back to the start using your abs.', false),
  ('treadmill', null, 'Treadmill', 'quads', array['calves', 'hamstrings']::text[], 'Machine', 'Cardio', 'Beginner', 'cardio', 'Walk, jog or run on the treadmill. Log the time in minutes.', false),
  ('cycling', null, 'Stationary Bike', 'quads', array['calves', 'hamstrings']::text[], 'Machine', 'Cardio', 'Beginner', 'cardio', 'Cycle at a steady or interval pace. Log the time in minutes.', false),
  ('rowing-machine', null, 'Rowing Machine', 'back', array['quads', 'biceps']::text[], 'Machine', 'Cardio', 'Beginner', 'cardio', 'Drive with your legs first, then lean back and pull the handle to your ribs. Log the time in minutes.', false)
